import{_ as t,C as o,o as s,c as l,j as i,E as r,a as d,a3 as h}from"./chunks/framework.C6R8kWFE.js";const z=JSON.parse(`{"title":"1-hafta","description":"","frontmatter":{"title":"1-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"9-sinf (UX/UI)","link":"/9-sinf/"},"n":1,"bob":"I-bob · UX/UI dizayn nazariyasi va asoslari","lessons":[{"g":1,"title":"UX va UI dizayn tushunchalari: nima va nima uchun","lead":"Har kuni Telegram, Instagram yoki o'yinlarni ochasiz, lekin ularning ko'rinishi va qulayligi ortida kimdir turganini o'ylab ko'rganmisiz? Bugun siz ikkita sirli qisqartma, UX va UI, ni ajratishni o'rganasiz va ilovalarga dizayner ko'zi bilan qaraysiz.","link":"/9-sinf/hafta-01/dars-1","slide":"/slaydlar/9-sinf/hafta-01/dars-1.html","test":"/slaydlar/9-sinf/hafta-01/dars-1-test.html"},{"g":2,"title":"UX/UI dizayn tamoyillari va jarayoni: yaxshi dizayn qanday bo'ladi","lead":"Nega bir ilovani «o'zi tushunarli» deymiz, boshqasida esa adashib qolamiz? Bugun yaxshi dizaynni ajratadigan aniq qoidalarni (4C va 7 ta UX tamoyili) va dizayn qanday bosqichlardan o'tishini o'rganamiz.","link":"/9-sinf/hafta-01/dars-2","slide":"/slaydlar/9-sinf/hafta-01/dars-2.html","test":"/slaydlar/9-sinf/hafta-01/dars-2-test.html"},{"g":3,"title":"Foydalanuvchi tadqiqotlari: nega, qanday usullar va persona","lead":"Yaxshi dizayner chizishdan oldin so'raydi, kuzatadi va tinglaydi. Bugun siz sinfdoshingizdan haqiqiy intervyu olasiz va uning «portreti» (persona) ni yasaysiz.","link":"/9-sinf/hafta-01/dars-3","slide":"/slaydlar/9-sinf/hafta-01/dars-3.html","test":"/slaydlar/9-sinf/hafta-01/dars-3-test.html"}],"test":"/slaydlar/9-sinf/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"9-sinf/hafta-01/index.md","filePath":"9-sinf/hafta-01/index.md"}`),e={name:"9-sinf/hafta-01/index.md"},u={class:"blk"},y={id:"uyga-vazifa",tabindex:"-1"};function g(b,a,m,q,v,f){const n=o("Icon");return s(),l("div",null,[i("div",u,[i("h2",y,[r(n,{name:"house"}),a[0]||(a[0]=d(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=h('<p>Har bir vazifa 20–30 daqiqa. Natijalarni daftarda yoki bitta hujjatda (Google Docs, Notes, Figma/Canva) saqlang; skrinshot va rasmlarni shu hujjatga qo&#39;shing. Topshirish: keyingi dars boshida mentorga ko&#39;rsating (daftar, hujjat yoki telefondagi rasm).</p><h3 id="_1-dars-uchun-ux-va-ui-tushunchalari" tabindex="-1">1-dars uchun (UX va UI tushunchalari) <a class="header-anchor" href="#_1-dars-uchun-ux-va-ui-tushunchalari" aria-label="Permalink to &quot;1-dars uchun (UX va UI tushunchalari)&quot;">​</a></h3><p><strong>1-topshiriq: «Mening ilovamda yaxshi va yomon UX»</strong> (20–25 daqiqa)</p><ol><li>O&#39;zingiz kunda foydalanadigan bitta ilovani tanlang (masalan, Telegram, Click, YouTube, maktab ilovasi).</li><li>Ilovani ochib, oddiy bitta ishni bajaring (xabar yuborish, to&#39;lov qilish, video topish) va jarayonni kuzating.</li><li>Bitta yaxshi UX nuqtasini toping: qaysi joyi sizga qulay yoki tushunarli?</li><li>Bitta yomon UX nuqtasini toping: qayerda to&#39;xtab qoldingiz, adashdingiz yoki asabiylashdingiz?</li><li>Har biri uchun skrinshot oling yoki 1–2 gapda tavsiflang va nega shunday ekanini bir jumlada yozing.</li><li>Oxirida bir gap yozing: bu nuqta UX ga (tajriba, qulaylik) tegishlimi yoki UI ga (ko&#39;rinish) tegishlimi?</li></ol><p><strong>Kutiladigan natija:</strong> bitta ilova, bitta yaxshi va bitta yomon nuqta, har birining sababi bir jumlada; UX va UI farqini ishlatgan holda yozilgan. <strong>Nimani topshirasiz:</strong> daftar yozuvi yoki hujjat (skrinshotlar bilan).</p><h3 id="_2-dars-uchun-ux-tamoyillari-va-dizayn-jarayoni" tabindex="-1">2-dars uchun (UX tamoyillari va dizayn jarayoni) <a class="header-anchor" href="#_2-dars-uchun-ux-tamoyillari-va-dizayn-jarayoni" aria-label="Permalink to &quot;2-dars uchun (UX tamoyillari va dizayn jarayoni)&quot;">​</a></h3><p><strong>2-topshiriq: «Uch ekranni 4C bo&#39;yicha baholash»</strong> (20–30 daqiqa)</p><ol><li>Bitta ilovani tanlang (1-vazifadagi bilan bir xil bo&#39;lishi shart emas).</li><li>Uning 3 ta ekranini tanlang (masalan, bosh sahifa, qidiruv, sozlamalar). Har biriga skrinshot oling yoki nomini yozing.</li><li>4C jadvalini tuzing: qatorlarda Control, Consistency, Comfortability, Cognitive Load; ustunlarda 3 ta ekran.</li><li>Har bir tamoyil uchun bitta aniq dalil yozing: ekranda aynan nima buni ko&#39;rsatadi? («Qulay» kabi umumiy gap yetarli emas.)</li><li>Har bir tamoyilga belgi qo&#39;ying: «yaxshi» yoki «buzilgan».</li><li>Bitta eng zaif joyni tanlab, uni qanday yaxshilash mumkinligini bir gapda taklif qiling.</li></ol><p><strong>Kutiladigan natija:</strong> to&#39;ldirilgan 4C jadvali, har bir tamoyil uchun bitta dalil, bitta taklif. <strong>Nimani topshirasiz:</strong> jadvalning rasmi yoki hujjati (3 ekran skrinshoti bilan).</p><h3 id="_3-dars-uchun-foydalanuvchi-tadqiqotlari-i" tabindex="-1">3-dars uchun (Foydalanuvchi tadqiqotlari I) <a class="header-anchor" href="#_3-dars-uchun-foydalanuvchi-tadqiqotlari-i" aria-label="Permalink to &quot;3-dars uchun (Foydalanuvchi tadqiqotlari I)&quot;">​</a></h3><p><strong>3-topshiriq: «Intervyu va persona»</strong> (20–30 daqiqa)</p><ol><li>Sinfdoshdan farqli kamida 3 ta odam toping (oila a&#39;zosi, boshqa yoshdagi odam, qo&#39;shni).</li><li>Har biridan bitta ilova yoki xizmat (masalan, kitob izlash, to&#39;lov, taksi chaqirish) haqida 5 daqiqalik intervyu oling. 5 ta ochiq savol oldindan yozib qo&#39;ying (dars daftaridagi shablondan foydalaning).</li><li>Javoblarni yozib boring: savol, javob, qiziq iqtibos. Maslahat bermang, ko&#39;proq tinglang.</li><li>Yozuvlarni qayta o&#39;qing va takrorlanadigan odat, motivatsiya va og&#39;riq nuqtalarini belgilang.</li><li>Shundan bitta persona kartasini tuzing: xayoliy ism va yosh, odat, motivatsiya, og&#39;riq nuqtasi, maqsad va bitta iqtibos.</li><li>Kartadagi har bir band intervyudagi qaysi javobdan kelib chiqqanini yonida qisqa yozing.</li></ol><p><strong>Kutiladigan natija:</strong> 3 ta intervyuning yozuvi va bitta persona kartasi; karta o&#39;ylab topilmagan, intervyudagi faktlarga asoslangan. <strong>Nimani topshirasiz:</strong> daftardagi yozuv va kartaning rasmi (skrinshot yoki foto). Keyingi darsda shu kartadan ssenariy yozamiz.</p>',13))])])}const c=t(e,[["render",g]]);export{z as __pageData,c as default};
